window.docContents[87].resolve({"/IndProp/#Logical-Foundations--IndProp___-Inductively-Defined-Propositions--Inductively-Defined-Propositions--Example___-Binary-Relation-for-Comparing-Numbers":{"contents":"A binary relation on a set α has Lean type α → α → Prop.\nThis is a family of propositions parameterized by two elements\nof α ─ i.e., a proposition about pairs of elements of α.\n\nFor example, one familiar binary relation on Nat is\nLe : Nat → Nat → Prop, the less-than-or-equal-to relation,\nwhich can be inductively defined by the following two rules:\n\n  ─────── (le_refl)\n  Le n n\n\n  Le n m\n──────────── (le_step)\nLe n (m + 1)\n\n\n\n\nnamespace LePlayground\n\ninductive Le : Nat → Nat → Prop where\n  | refl {n : Nat}                : Le n n\n  | step {n m : Nat} (h : Le n m) : Le n (m + 1)\n\nscoped infix:50 (priority := high) \" ≤ \" => Le\n\n\n\n\nexample : 3 ≤ 5 := by\n  apply Le.step; apply Le.step; exact Le.refl\n\nend LePlayground\n\n\n","context":"Logical Foundations\u0009IndProp: Inductively Defined Propositions\u0009Inductively Defined Propositions","header":"9.1.2. Example: Binary Relation for Comparing Numbers","id":"/IndProp/#Logical-Foundations--IndProp___-Inductively-Defined-Propositions--Inductively-Defined-Propositions--Example___-Binary-Relation-for-Comparing-Numbers"}});